mapper.select:
SELECT refund_order.refund_order_id AS refundOrderId, refund_order.payment_order_id AS paymentOrderId, prepay_order.pay_scene AS payScene, refund_order.order_no AS orderNo, refund_order.customer_name AS customerName, CONCAT('¥', FORMAT(refund_amount, 2)) AS refundAmount, refund_method AS refundMethod, status, status_type AS statusType, DATE_FORMAT(applied_at, '%Y-%m-%d %H:%i:%s') AS appliedAt, CASE WHEN success_at IS NULL THEN '-' ELSE DATE_FORMAT(success_at, '%Y-%m-%d %H:%i:%s') END AS successAt, CASE WHEN terminal_at IS NULL THEN '-' ELSE DATE_FORMAT(terminal_at, '%Y-%m-%d %H:%i:%s') END AS terminalAt, channel_code AS channelCode, channel_refund_no AS channelRefundNo, CASE WHEN channel_submitted_at IS NULL THEN '-' ELSE DATE_FORMAT(channel_submitted_at, '%Y-%m-%d %H:%i:%s') END AS channelSubmittedAt FROM t_refund_order refund_order
refund_order.refund_order_id LIKE CONCAT('%', #{query.refundOrderIdLikePattern}, '%') ESCAPE '!'
AND refund_order.payment_order_id LIKE CONCAT('%', #{query.paymentOrderIdLikePattern}, '%') ESCAPE '!'
AND status = 'SUCCESS' AND success_at IS NULL
AND
AND
AND status IN ('REVIEWING', 'PROCESSING')
AND status = #{query.refundStatus}
AND refund_method = #{query.refundMethod}
LIMIT #{query.limit} OFFSET #{query.offset}
